"""Module 14: quantum sensing, the Heisenberg limit with GHZ states."""
from __future__ import annotations

import numpy as np

from .circuit import ghz_circuit, Circuit


def quantum_fisher_information(psi: np.ndarray, n: int) -> float:
    """QFI for a phase generated by G = (1/2) sum_i Z_i is 4 Var(G)."""
    zs = np.zeros(2 ** n)
    for x in range(2 ** n):
        zs[x] = sum(1 - 2 * ((x >> (n - 1 - q)) & 1) for q in range(n)) / 2
    p = np.abs(psi) ** 2
    mean = (p * zs).sum()
    return float(4 * ((p * zs ** 2).sum() - mean ** 2))


def product_state(n: int) -> np.ndarray:
    c = Circuit(n)
    for q in range(n):
        c.h(q)
    return c.state()


def ghz_parity_signal(n: int, phi: float) -> float:
    """<X...X> of a GHZ state after each qubit acquires phase phi: cos(n phi)."""
    c = ghz_circuit(n)
    for q in range(n):
        c.rz(phi, q)
    return c.expectation("X" * n)


def phase_uncertainty(qfi: float, repetitions: int = 1) -> float:
    """Cramer-Rao bound: delta phi >= 1 / sqrt(nu * QFI)."""
    return 1 / np.sqrt(repetitions * qfi)
